# --- Auth helper ---

get_auth_header() {
  if [ -n "${MCP_UPSTREAM_TOKEN:-}" ]; then
    printf '%s' "Authorization: Bearer ${MCP_UPSTREAM_TOKEN}"
  fi
}

# --- Session helpers ---

init_session() {
  echo "[*] Initializing MCP session at $SERVER_URL ..." >&2
  local headers_file
  headers_file=$(mktemp)

  local curl_args=(
    -s -D "$headers_file"
    --noproxy '*'
    -X POST "$SERVER_URL"
    -H "Content-Type: application/json"
    -d '{"jsonrpc":"2.0","id":0,"method":"initialize","params":{"protocolVersion":"2024-11-05","capabilities":{},"clientInfo":{"name":"client","version":"1.0"}}}'
  )

  local auth_header
  auth_header=$(get_auth_header)
  if [ -n "$auth_header" ]; then
    curl_args+=(-H "$auth_header")
  fi

  local body
  body=$(curl "${curl_args[@]}")

  SESSION_ID=$(grep -oi "Mcp-Session-Id: [^ ]*" "$headers_file" | head -1 | awk '{print $2}' | tr -d '"\r' || true)
  rm -f "$headers_file"
  if [ -z "$SESSION_ID" ]; then
    echo "[!] Failed to get session ID. Is the server running?" >&2
    echo "[!] Response: $body" >&2
    return 1
  fi
  echo "[+] Session: $SESSION_ID" >&2
}

# --- MCP JSON-RPC helpers ---

mcp_request() {
  local method="$1"
  local id="${2:-1}"
  local params
  if [ $# -ge 3 ]; then params="$3"; else params='{ }'; fi

  if [ -z "$SESSION_ID" ]; then
    init_session
  fi

  local curl_args=(
    -s --noproxy '*'
    -X POST "$SERVER_URL"
    -H "Content-Type: application/json"
    -H "Mcp-Session-Id: $SESSION_ID"
    -d "{\"jsonrpc\":\"2.0\",\"id\":$id,\"method\":\"$method\",\"params\":$params}"
  )

  local auth_header
  auth_header=$(get_auth_header)
  if [ -n "$auth_header" ]; then
    curl_args+=(-H "$auth_header")
  fi

  curl "${curl_args[@]}"
}

# --- Tool helpers ---

list_tools() {
  echo "[*] Listing tools ..." >&2
  local result
  result=$(mcp_request tools/list 1)
  if command -v python3 >/dev/null 2>&1; then
    echo "$result" | python3 -c '
import json, sys
try:
    data = json.load(sys.stdin)
    tools = data.get("result", {}).get("tools", [])
    maxlen = max((len(t["name"]) for t in tools), default=0)
    for t in tools:
        desc = t.get("description", "")
        if desc:
            # take first line only
            desc = desc.split("\n")[0].strip()
        name = t["name"]
        print(f"  {name:<{maxlen+4}}{desc}")
except Exception as e:
    print("(parse error: {})".format(e), file=sys.stderr)
'
  else
    # Fallback: print raw result
    echo "$result"
  fi
}

call_tool() {
  local tool_name="${1:?Usage: call_tool <tool-name> [--key value ...] [--body '<json>']}"
  shift
  local args='{}'
  local file_path=""
  local body_json=""

  # Detect argument style: --key value pairs (new) vs positional JSON (legacy).
  if [ $# -gt 0 ] && [ "${1#--}" != "$1" ]; then
    # New style: --key value [--key value ...] [--body '<json>'] [--file <path>]
    while [ $# -gt 0 ]; do
      case "$1" in
        --file=*)
          file_path="${1#--file=}"
          shift
          ;;
        --file)
          file_path="${2:?--file requires a path argument}"
          shift 2
          ;;
        --body=*)
          body_json="${1#--body=}"
          shift
          ;;
        --body)
          body_json="${2:?--body requires a JSON value}"
          shift 2
          ;;
        --*)
          local key="${1#--}"
          local value
          if [[ "$key" == *"="* ]]; then
            # Support --key=value syntax
            value="${key#*=}"
            key="${key%%=*}"
            shift
          else
            value="${2:?$1 requires a value}"
            shift 2
          fi
          if command -v python3 >/dev/null 2>&1; then
            # Parse value: try JSON first, fall back to string.
            args=$(python3 -c "
import json, sys
v = '''$value'''
# Try JSON parse; if it fails treat as raw string.
try:    v = json.loads(v)
except: pass
args = json.loads('''$args''')
args['$key'] = v
print(json.dumps(args))
" 2>/dev/null || echo "$args")
          else
            # Minimal fallback: always treat as string.
            args=$(echo "$args" | sed 's/}$//')
            args="${args},\"$key\":\"$value\"}"
          fi
          ;;
        *)
          shift
          ;;
      esac
    done

    # If --file is provided, auto-prefix @file:// and set as the "file" arg.
    if [ -n "$file_path" ]; then
      if [ ! -f "$file_path" ]; then
        echo "[!] File not found: $file_path" >&2
        return 1
      fi
      local abs_path
      abs_path=$(realpath "$file_path" 2>/dev/null || echo "$file_path")
      local file_size
      file_size=$(wc -c < "$file_path" | tr -d ' ')
      echo "[*] Uploading file via ref: @file://$abs_path ($file_size bytes)" >&2
      if command -v python3 >/dev/null 2>&1; then
        args=$(python3 -c "
import json
args = json.loads('''$args''')
args['file'] = '@file://$abs_path'
print(json.dumps(args))
" 2>/dev/null || echo "$args")
      fi
    fi

    # Merge --body into args.
    if [ -n "$body_json" ]; then
      if command -v python3 >/dev/null 2>&1; then
        args=$(python3 -c "
import json
args = json.loads('''$args''')
args['body'] = json.loads('''$body_json''')
print(json.dumps(args))
" 2>/dev/null || echo "$args")
      fi
    fi
  else
    # Legacy style: positional JSON arg with optional --file.
    while [ $# -gt 0 ]; do
      case "$1" in
        --file)
          file_path="${2:?--file requires a path argument}"
          shift 2
          ;;
        *)
          args="$1"
          shift
          ;;
      esac
    done

    # If --file is provided, set as file ref URI arg.
    if [ -n "$file_path" ]; then
      if [ ! -f "$file_path" ]; then
        echo "[!] File not found: $file_path" >&2
        return 1
      fi
      local abs_path
      abs_path=$(realpath "$file_path" 2>/dev/null || echo "$file_path")
      local file_size
      file_size=$(wc -c < "$file_path" | tr -d ' ')
      echo "[*] Uploading file via ref: @file://$abs_path ($file_size bytes)" >&2
      if command -v python3 >/dev/null 2>&1; then
        args=$(python3 -c "
import json
args = json.loads('$args')
args['file'] = '@file://$abs_path'
print(json.dumps(args))
" 2>/dev/null || echo "$args")
      fi
    fi
  fi

  echo "[*] Calling tool: $tool_name" >&2
  echo "[*] Args: $args" >&2

  local result
  result=$(mcp_request tools/call 1 "{\"name\":\"$tool_name\",\"arguments\":$args}")

  # Check for error
  if echo "$result" | grep -q '"isError":true'; then
    echo "[!] Tool returned an error:" >&2
    echo "$result" | python3 -m json.tool 2>/dev/null || echo "$result"
    return 1
  fi

  # Pretty print JSON response
  echo "$result" | python3 -m json.tool 2>/dev/null || echo "$result"
}

# --- Main ---

case "${1:-help}" in
  help|--help|-h)
    usage
    ;;
  list-tools|list)
    init_session
    list_tools
    ;;
  call)
    shift
    init_session
    call_tool "$@"
    ;;
  *)
    init_session
    call_tool "$@"
    ;;
esac
